extends Node
## Persistent menu player. Current catalogue contains the one owner-supplied track.
const TRACK="res://assets/menu/opening/B-22_Dead_Street.mp3"
var player: AudioStreamPlayer
var layer: CanvasLayer
var surface: Control
var dock: Button
var panel: PanelContainer
var toast: PanelContainer
var label: Label
var toggle: Button
var enabled_check: CheckBox
var volume: HSlider
var sandbox
var in_sandbox=false
var entry_clock=0.0
var signature_started=false
var play_count=0
var user_paused=false
var track_enabled=true
var last_clock=0.0
var output_latency=0.0
var settings_path="user://dead_street_music.cfg"

func _ready():
	player=AudioStreamPlayer.new(); add_child(player); player.volume_db=-4.0
	var stream=AudioStreamMP3.new(); stream.data=FileAccess.get_file_as_bytes(TRACK); player.stream=stream
	player.finished.connect(finished)
	output_latency=AudioServer.get_output_latency()
	var cfg=ConfigFile.new()
	if cfg.load(settings_path)==OK: track_enabled=bool(cfg.get_value("playlist","dead_street",true))
	layer=CanvasLayer.new(); layer.layer=90; add_child(layer); layer.hide()
	surface=Control.new(); layer.add_child(surface); surface.mouse_filter=Control.MOUSE_FILTER_IGNORE
	dock=Button.new(); surface.add_child(dock); dock.text="▥  Music   ⌄"; dock.size=Vector2(123,36)
	dock.pressed.connect(toggle_panel)
	panel=PanelContainer.new(); surface.add_child(panel); panel.custom_minimum_size=Vector2(282,245); panel.hide()
	style(panel)
	var margin=MarginContainer.new(); panel.add_child(margin)
	for side in ["left","top","right","bottom"]: margin.add_theme_constant_override("margin_"+side,14)
	var box=VBoxContainer.new(); margin.add_child(box); box.add_theme_constant_override("separation",9)
	var head=HBoxContainer.new(); box.add_child(head)
	var heading=Label.new(); heading.text="Music"; heading.add_theme_font_size_override("font_size",20); heading.size_flags_horizontal=Control.SIZE_EXPAND_FILL; head.add_child(heading)
	var close=Button.new(); close.text="×"; close.pressed.connect(func():panel.hide()); head.add_child(close)
	var now=Label.new(); now.text="NOW PLAYING"; now.add_theme_font_size_override("font_size",10); now.modulate=Color("#b4babc"); box.add_child(now)
	label=Label.new(); label.text="Dead Street\nB-22"; label.add_theme_font_size_override("font_size",16); box.add_child(label)
	var order=Label.new(); order.text="SHUFFLE ORDER"; order.add_theme_font_size_override("font_size",10); order.modulate=Color("#b4babc"); box.add_child(order)
	enabled_check=CheckBox.new(); enabled_check.text="Dead Street — B-22"; enabled_check.button_pressed=track_enabled; box.add_child(enabled_check)
	enabled_check.toggled.connect(func(on):track_enabled=on; save_settings())
	var actions=HBoxContainer.new(); box.add_child(actions)
	toggle=Button.new(); toggle.text="Pause"; toggle.pressed.connect(pause_music); actions.add_child(toggle)
	var skip=Button.new(); skip.text="Next"; skip.disabled=true; skip.tooltip_text="No other tracks in this playlist yet."; actions.add_child(skip)
	volume=HSlider.new(); volume.min_value=0; volume.max_value=1; volume.step=0.01; volume.value=db_to_linear(-4.0); volume.size_flags_horizontal=Control.SIZE_EXPAND_FILL; actions.add_child(volume)
	volume.value_changed.connect(func(value):player.volume_db=linear_to_db(maxf(value,0.0001)))
	toast=PanelContainer.new(); surface.add_child(toast); toast.size=Vector2(282,93); style(toast)
	var text=Label.new(); text.text="NOW PLAYING\nDead Street\nB-22"; text.position=Vector2(14,10); text.add_theme_font_size_override("font_size",16)
	var tm=MarginContainer.new(); tm.add_theme_constant_override("margin_left",14); tm.add_theme_constant_override("margin_top",10); tm.add_theme_constant_override("margin_right",14); tm.add_theme_constant_override("margin_bottom",10); toast.add_child(tm); tm.add_child(text)

func style(control: Control):
	var bg=StyleBoxFlat.new(); bg.bg_color=Color("#0b1317"); bg.border_color=Color("#939d9f"); bg.set_border_width_all(1)
	control.add_theme_stylebox_override("panel",bg)

func start_signature():
	if signature_started:return
	signature_started=true; player.play(); play_count+=1; last_clock=0

func clock() -> float:
	if not signature_started:return 0.0
	if player.stream_paused:return last_clock
	var t=player.get_playback_position()+AudioServer.get_time_since_last_mix()-output_latency
	last_clock=maxf(last_clock,maxf(0.0,t)); return last_clock

func show_on_entry():
	in_sandbox=true; entry_clock=Time.get_ticks_msec()/1000.0; layer.show(); toast.show(); dock.hide()

func _process(_delta: float):
	if not in_sandbox:return
	var menu_visible=is_instance_valid(sandbox) and sandbox.ui.visible
	layer.visible=menu_visible
	player.stream_paused=user_paused or not menu_visible
	var viewport=get_viewport().get_visible_rect().size; surface.size=viewport
	var factor=minf(1.0,minf(viewport.x/1280.0,viewport.y/720.0)); surface.scale=Vector2.ONE*factor
	var area=viewport/factor; var elapsed=Time.get_ticks_msec()/1000.0-entry_clock
	dock.position=area-Vector2(151,51); panel.position=area-Vector2(310,315)
	toast.position=area-Vector2(310,140)
	if elapsed>=3.0:
		var q=clampf((elapsed-3.0)/0.75,0.0,1.0)
		toast.position=toast.position.lerp(dock.position,q); toast.scale=Vector2.ONE.lerp(Vector2(0.436,0.387),q); toast.modulate.a=1-q
		if q>=1:toast.hide();dock.show()

func toggle_panel(): panel.visible=not panel.visible
func pause_music():
	user_paused=not user_paused; toggle.text="Play" if user_paused else "Pause"
	if not user_paused and not player.playing:player.play(); play_count+=1; last_clock=0.0
func finished():
	# With one track, wait for a deliberate replay instead of immediately repeating it.
	user_paused=true; toggle.text="Play"
func save_settings():
	var cfg=ConfigFile.new(); cfg.set_value("playlist","dead_street",track_enabled); cfg.save(settings_path)
func _unhandled_key_input(event: InputEvent):
	if not in_sandbox or not layer.visible:return
	if event is InputEventKey and event.pressed and not event.echo and event.keycode==KEY_M:
		toggle_panel();get_viewport().set_input_as_handled()

"""Package the accepted opening and current sandbox into a separate native runtime."""
from pathlib import Path
import hashlib,json,shutil,subprocess,sys,time,re
repo=Path(r'C:\Users\brand\OneDrive\Documents\dead-street')
out=repo/'tools/menu_title_20260914/native'
base=Path(r'C:\Users\brand\AppData\Local\DeadStreetTools\godot_release_4.7.2')
stage=Path(r'C:\Users\brand\AppData\Local\DeadStreetTools\sandbox_opening_20260914')
editor=Path(r'C:\Users\brand\OneDrive\Documents\Godot\Godot_v4.7.2-stable_win64_console.exe')
mode=sys.argv[1] if len(sys.argv)>1 else 'smoke'
assert mode in ('smoke','record','package')
stage.mkdir(exist_ok=True);snapshot=stage/'source_snapshot';snapshot.mkdir(exist_ok=True)
files={x['path']:x['source'] for x in json.loads((base/'package/launcher_manifest.json').read_text())}
hashes={}
for folder in ('battle','campaign','core','gameplay'):
 for path in (repo/folder).rglob('*'):
  if path.suffix not in ('.gd','.tscn'):continue
  relative=path.relative_to(repo).as_posix();dest=snapshot/relative
  if not dest.exists() or relative in ('gameplay/sandbox_opening.gd','gameplay/sandbox_opening.tscn','gameplay/sandbox_menu_music.gd'):
   dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(path,dest)
  files[relative]=str(dest);hashes[relative]=hashlib.sha256(dest.read_bytes()).hexdigest()
for path in (repo/'assets/audio/convoy').glob('*.wav'):
 if path.stem!='trc_horn':files[path.relative_to(repo).as_posix()]=str(path)
for path in (repo/'assets/art/whittaker_estate').rglob('*.png'):files[path.relative_to(repo).as_posix()]=str(path)
files={k:v for k,v in files.items() if not k.startswith('assets/audio/factions/') and k!='gameplay/tactical_faction_voices.gd'}
for path in (repo/'assets/art').rglob('*portraits.png'):
 files[path.relative_to(repo).as_posix()]=str(path);imp=Path(str(path)+'.import')
 if imp.exists():
  files[imp.relative_to(repo).as_posix()]=str(imp)
  for target in re.findall(r'path="res://([^"]+)"',imp.read_text()):
   if (repo/target).exists():files[target]=str(repo/target)
for folder in ('assets/tutorial','assets/menu/opening'):
 for path in (repo/folder).rglob('*'):
  if path.is_file() and path.suffix in ('.png','.json','.ogv','.mp3'):files[path.relative_to(repo).as_posix()]=str(path)
files['tools/menu_title_20260914/native/validate.gd']=str(out/'validate.gd')
boot='''extends Node
func _ready():
 if not ProjectSettings.load_resource_pack(DATA_PACK,false):get_tree().quit(5);return
 if "--opening-check" in OS.get_cmdline_user_args():
  var tree=get_tree();tree.set_script(load("res://tools/menu_title_20260914/native/validate.gd"));tree.call_deferred("_initialize")
 else:
  get_tree().root.add_child(load("res://gameplay/sandbox_opening.tscn").instantiate())
 queue_free()
'''.replace('DATA_PACK',json.dumps((base/'benchmark_data.pck').as_posix()))
(stage/'boot.gd').write_text(boot);files['tools/bridge_perf/headroom/release_boot.gd']=str(stage/'boot.gd')
(stage/'override.cfg').write_text('[display]\nwindow/size/viewport_width=1280\nwindow/size/viewport_height=720\nwindow/size/window_width_override=1280\nwindow/size/window_height_override=720\nwindow/stretch/mode="disabled"\n[application]\nconfig/name="Dead Street - Battle Sandbox"\n')
files['override.cfg']=str(stage/'override.cfg')
manifest=stage/'manifest.json';manifest.write_text(json.dumps([dict(path=k,source=v) for k,v in files.items()]))
builder='''extends SceneTree
func _initialize():
 var p=PCKPacker.new()
 if p.pck_start(PACK)!=OK:quit(2);return
 for row in JSON.parse_string(FileAccess.get_file_as_string(MANIFEST)):
  if p.add_file("res://"+row.path,row.source)!=OK:quit(3);return
 if p.flush()!=OK:quit(4);return
 quit()
'''.replace('PACK',json.dumps((stage/'godot.pck').as_posix())).replace('MANIFEST',json.dumps(manifest.as_posix()))
(stage/'build_pack.gd').write_text(builder);(stage/'project.godot').write_text('config_version=5\n[application]\nconfig/name="Opening packaging"\n')
r=subprocess.run([str(editor),'--headless','--path',str(stage),'--script',str(stage/'build_pack.gd')],capture_output=True,timeout=90)
(out/'pack.log').write_bytes(r.stdout+r.stderr);assert r.returncode==0,(r.stdout+r.stderr)[-6000:]
shutil.copy2(base/'godot.exe',stage/'godot.exe')
for dll in base.glob('*.dll'):shutil.copy2(dll,stage/dll.name)
(out/'source_hashes.json').write_text(json.dumps(hashes,indent=2))
(out/'snapshot.json').write_text(json.dumps({'head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip(),'source_snapshot':str(snapshot),'runtime':str(stage/'godot.exe'),'pack_sha256':hashlib.sha256((stage/'godot.pck').read_bytes()).hexdigest(),'shared_runtime_modified':False},indent=2))
print('NATIVE_PACKAGE_READY',mode,flush=True)
if mode=='package':sys.exit(0)
args=[str(stage/'godot.exe'),'--resolution','1280x720','--position','10,10','--disable-vsync']
if mode=='record':args+=['--write-movie',str(out/'opening_native_raw.avi'),'--fixed-fps','30']
args+=['--','--opening-check']
if mode=='record':args+=['--record']
with (out/(mode+'.log')).open('wb') as log:
 p=subprocess.Popen(args,cwd=stage,stdout=log,stderr=subprocess.STDOUT);print('NATIVE_CHECK_PID',p.pid,flush=True);start=time.monotonic()
 while p.poll() is None:
  try:p.wait(timeout=1)
  except subprocess.TimeoutExpired:pass
  content=(out/(mode+'.log')).read_text(errors='replace')
  if 'SCRIPT ERROR' in content or time.monotonic()-start>400:
   p.kill();p.wait();raise RuntimeError(content[-6000:])
assert p.returncode==0,p.returncode
print('NATIVE_CHECK_COMPLETE',mode,flush=True)
